'with w_best_round as (
  select course_id, h, score
  from (
    select course_id, h, score, row_number()  over (partition by course_id, h order by people desc) rn
    from (
        select u.course_id, u.h, u.score, count(*) people
          from  wmg_rounds_unpivot_mv u
         where u.player_id != 0  -- remove the curated system score
         group by u.course_id, u.h, u.score
    )
  )
 where rn = 1
)
, w_realistic as (
select *
from w_best_round
 pivot (
   max(score) for h in (
    1 as h1,
    2 as h2,
    3 as h3,
    4 as h4,
    5 as h5,
    6 as h6,
    7 as h7,
    8 as h8,
    9 as h9,
    10 as h10,
    11 as h11,
    12 as h12,
    13 as h13,
    14 as h14,
    15 as h15,
    16 as h16,
    17 as h17,
    18 as h18
   )
 )
)
select c.course_id, c.code, c.name, c.course_group, c.course_mode, c.release_order, c.release_date
      , c.h1
