     , r.h18 realistic_h18
    , r.h1+ r.h2+ r.h3+ r.h4+ r.h5+ r.h6+ r.h7+ r.h8+ r.h9+ r.h10+ r.h11+ r.h12+ r.h13+ r.h14+ r.h15+ r.h16+ r.h17+ r.h18 - c.course_par course_realistic_score
    , c.best_under utopian
from wmg_courses_v c
