                      select json_arrayagg(u.par order by u.h)
                       from wmg_rounds_unpivot_mv u
                      where u.player_id = r.player_id
                        and u.course_id = s.easy_course_id
                        and u.week = r.week
                     )
         ' || '         , ''hardRoundTotal''  value r.hard_roundTotal
                  , ''hardRoundScore''  value r.hard_roundScore
                  , ''hardScorecard''   value (
                      select json_arrayagg(u.par order by u.h)
                       from wmg_rounds_unpivot_mv u
                      where u.player_id = r.player_id
                        and u.course_id = s.hard_course_id
                        and u.week = r.week
                     ) RETURNING CLOB 
               ) RETURNING CLOB
             ) 
             from (
             select week
                  , account
                  , rank_code
                  , player_id
                  , easy_roundScore
                  , hard_roundScore
                  , easy_roundTotal
                  , hard_roundTotal
             from (

             select r.week
                  , r.account
                  , r.rank_code
                  , r.player_id
                  , r.round_strokes' || '
                  , r.under_par
                  , tc.course_no
               from wmg_rounds_v r
                   , wmg_tournament_courses tc
              where r.tournament_session_id = tc.tournament_session_id
                and r.course_id = tc.course_id
