      p_comments       => 'Unregister player from tournament session');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'WMGT Tournament',
      p_pattern        => 'unregister',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_items_per_page => 0,
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Unregister a Discord user from a tournament session',
      p_source         => 
'declare
  l_body clob;
  l_json json_object_t;
  l_discord_user t_discord_user;
  l_session_id number;
  l_existing_registration number;
  l_week varchar2(10);
  l_registration_closed_flag varchar2(1);
  l_response clob;
  l_scope logger_logs.scope%type := ''REST:api/tournaments/unregister'';
begin
  logger.log(p_text => ''START'', p_scope => l_scope);

  -- Get request body
  l_body := :body_text;
  l_json := json_object_t.parse(l_body);

  -- Extract parameters
  l_session_id := l_json.get_number(''session_id'');

  logger.log(p_text => ''session_id: '' || l_session_id, p_scope => l_scope);

  -- Initialize Discord user from JSON
  l_discord_user := t_discord_user();
  l_discord_user.init_from_json(l_json.get_object(''discord_user'').to_clob());
  logger.log(p_text => ''.. discord_id: '' || l_discord_user.discord_id, p_scope => l_scope);
  logger.log(p_text => ''.. username: '' || l_discord_user.username, p_scope => l_scope);

  l_discord_user.sync_player();

  logger' || '.log(p_text => ''player_id: '' || l_discord_user.player_id, p_scope => l_scope);

  -- Check if session exists and get details
  select week,
         registration_closed_flag
  into l_week, l_registration_closed_flag
  from wmg_tournament_sessions
  where id = l_session_id;

  -- Check if tournament has started
  if l_registration_closed_flag = ''Y'' then
    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write(''success'', false);
    apex_json.write(''error_code'', ''UNREGISTRATION_FAILED'');
    apex_json.write(''message'', ''Cannot unregister after tournament has started'');
    apex_json.close_object;
    l_response := apex_json.get_clob_output;
    apex_json.free_output;
    goto output_response;
  end if;

  -- Check if player is registered
  select count(*)
  into l_existing_registration
  from wmg_tournament_players
  where tournament_session_id = l_session_id
    and player_id = l_discord_user.player_id
    and active_ind = ''Y'';

 ' || ' if l_existing_registration = 0 then
    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write(''success'', false);
    apex_json.write(''error_code'', ''NOT_REGISTERED'');
    apex_json.write(''message'', ''Player is not registered for this tournament session'');
    apex_json.close_object;
    l_response := apex_json.get_clob_output;
    apex_json.free_output;
    goto output_response;
  end if;

  -- Unregister player (set active_ind to N)
  wmg_util.process_registration(
    p_tournament_session_id => l_session_id
  , p_player_id   => l_discord_user.player_id
  , p_action      => ''UNREGISTER''
  , p_source      => ''API''
  );

  commit;

  apex_json.initialize_clob_output;
  apex_json.open_object;
  apex_json.write(''success'', true);
  apex_json.write(''message'', ''Successfully unregistered from '' || l_week);
  apex_json.close_object;
  l_response := apex_json.get_clob_output;
  apex_json.free_output;

  <<output_response>>
  apex_util.prn' || '(
    p_clob   => l_response,
    p_escape => false
  );

  logger.log(p_text => ''END'', p_scope => l_scope);
exception
  when no_data_found then
    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write(''success'', false);
    apex_json.write(''error_code'', ''SESSION_NOT_FOUND'');
    apex_json.write(''message'', ''Tournament session does not exist'');
    apex_json.close_object;
    l_response := apex_json.get_clob_output;
    apex_json.free_output;
    apex_util.prn(p_clob => l_response, p_escape => false);
    logger.log_error(p_text => ''Session not found: '' || l_session_id, p_scope => l_scope);
  when others then
    rollback;
    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write(''success'', false);
    apex_json.write(''error_code'', ''UNREGISTRATION_FAILED'');
    apex_json.write(''message'', ''Unregistration failed: '' || sqlerrm);
    apex_json.close_object;
    l_response := apex_json.get_clob_output;
    apex' || '_json.free_output;
    apex_util.prn(p_clob => l_response, p_escape => false);
    logger.log_error(p_text => sqlerrm, p_scope => l_scope);
end;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'WMGT Tournament',
      p_pattern        => 'votes',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => 'Show the current course votes');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'WMGT Tournament',
      p_pattern        => 'votes',
      p_method         => 'GET',
      p_source_type    => 'json/collection',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'with tournament_courses as (
    select s.round_num
         , count(*) over () setup_weeks
         , s.week
         , s.easy_course_code
         , s.easy_course_name
         , s.hard_course_code
         , s.hard_course_name
         , s.easy_course_id
         , s.easy_release_order
         , s.hard_course_id
         , s.hard_release_order
         , case 
             when s.completed_ind = ''Y'' then ''white_check_mark''
             when (s.open_registration_on is null or s.open_registration_on < localtimestamp) then ''golf''
              else ''clock1'' 
           end status
      -- halloween
      --   , case when s.completed_ind = ''Y'' then ''skull'' else ''jack_o_lantern'' end status
         , s.session_date
         , s.completed_ind
    from wmg_tournament_sessions_v s
       , wmg_courses e
       , wmg_courses h
    where s.tournament_id in (
        select id
          from wmg_tournaments
         where current_flag = ''Y''
    )
      and s.easy_' || 'course_id = e.id (+)
      and s.hard_course_id = h.id (+)
)
, w_votes as (
  select course_id, sum(vote) votes
  from wmg_course_vote
  group by course_id
)
, w_player_votes as (
  select course_id, vote, case vote when 1 then ''up'' when -1 then ''down'' else null end vote_selection 
  from wmg_course_vote
  where player_id = (select id from wmg_players where discord_id = :discord_id)
)
, missing_easy as (
select round_num
     , easy_course_group
     , easy_course
     , easy_name
     , '''' hard_course
     , '''' hard_name
     , status
     , release_order
     , votes easy_votes
     , vote_class easy_vote_class
from (
select to_number(null) round_num
     , e.course_group easy_course_group
     , e.code easy_course
     , tce.easy_course_code
     , e.name easy_name
     , ''lock'' status
     , e.release_order
     , v.votes
     , decode(pv.vote_selection, null, ''show'', ''hide'' || pv.vote_selection) vote_class
from wmg_courses e
   , w_votes v
   , ' || 'w_player_votes pv
   , tournament_courses tce
where e.course_mode = ''E''
  and e.code = tce.easy_course_code (+)
  and e.id = v.course_id (+)
  and e.id = pv.course_id (+)
)
where easy_course_code is null
)
, missing_hard as (
  select round_num
       , hard_course_group
       , '''' easy_course
       , '''' easy_name
       , hard_course
       , hard_name
       , status
       , release_order
       , votes hard_votes
       , vote_class hard_vote_class
  from (
    select to_number(null) round_num
         , h.course_group hard_course_group
         , h.code hard_course
         , h.name hard_name
         , tch.hard_course_code
         , ''lock'' status
         , h.release_order
         , v.votes
         , decode(pv.vote_selection, null, ''show'', ''hide'' || pv.vote_selection) vote_class
    from wmg_courses h
       , w_votes v
       , w_player_votes pv
       , tournament_courses tch
    where h.course_mode = ''H''
      and h.code = tch.hard_cours' || 'e_code (+)
      and h.id in (select ac.id from wmg_courses ac where ac.course_mode = ''H'' minus select easy_course_id from tournament_courses)
      and h.id = v.course_id (+)
      and h.id = pv.course_id (+)
  )
  where hard_course_code is null
)
, w_easy as (
select /* q("easy_votes") */ e.easy_votes easy_votes
     , case when e.easy_votes is not null and rank() over (order by e.easy_votes desc nulls last) = 1 then ''top'' end easy_votes_top
     , row_number() over (order by e.easy_votes desc nulls last, e.easy_course_group) easy_vote_order
     , e.easy_course
     , e.easy_course_group
     , e.easy_name
     , e.easy_vote_class
     , e.status
     , case 
         when e.status = ''lock'' then ''Voting open''
         else ''Not eligible'' end status_title
     , e.release_order course_order
from missing_easy e
)
, w_hard as (
select /* q("hard_votes") */ h.hard_votes
     , case when h.hard_votes is not null and rank() over (order by h.hard_votes desc nulls la' || 'st) = 1 then ''top'' end hard_votes_top
     , row_number() over (order by h.hard_votes desc nulls last, h.hard_course_group) hard_vote_order
     , h.hard_course
     , h.hard_course_group
     , h.hard_name
     , h.hard_vote_class
     , h.status
     , case 
         when h.status = ''lock'' then ''Voting open''
         else ''Not eligible'' end status_title
     , h.release_order course_order
from missing_hard h
)
select e.easy_vote_order
     , h.hard_vote_order
     , e.easy_votes
     , e.easy_votes_top
     , e.easy_course
     , e.easy_name
     , h.hard_course
     , h.hard_name
     , h.hard_votes
     , h.hard_votes_top
from (select * from w_easy where easy_votes is not null) e
full outer join (select * from w_hard where hard_votes is not null) h
on e.easy_vote_order = h.hard_vote_order
order by 1 nulls last, 3

');

